sed -i '/val accountType = /i \    val roommates by viewModel.roommates.collectAsState()\n    val currentUserRoommate = roommates.find { it.id == currentUser?.uid }\n    var upiIdInput by remember(currentUserRoommate) { mutableStateOf(currentUserRoommate?.upiId ?: "") }\n    var upiIdError by remember { mutableStateOf(false) }' app/src/main/java/com/example/ui/screens/ProfileScreen.kt

sed -i '/keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done)/a \                    )\n                    OutlinedTextField(\n                        value = upiIdInput,\n                        onValueChange = {\n                            upiIdInput = it\n                            upiIdError = false\n                        },\n                        label = { Text("Your UPI ID") },\n                        leadingIcon = {\n                            Icon(imageVector = Icons.Default.Security, contentDescription = "UPI ID")\n                        },\n                        isError = upiIdError,\n                        supportingText = {\n                            if (upiIdError) {\n                                Text("UPI ID must contain @ and no spaces")\n                            } else {\n                                Text("Optional. Used for receiving payments.")\n                            }\n                        },\n                        modifier = Modifier\n                            .fillMaxWidth()\n                            .testTag("profile_upi_input"),\n                        singleLine = true,\n                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done)' app/src/main/java/com/example/ui/screens/ProfileScreen.kt
